<?php
require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_admin();
handle_post(function(){
    $values=[];foreach(['school_name'=>150,'campus'=>150,'report_header'=>300]as $key=>$max)$values[$key]=text_value($_POST,$key,$max);
    foreach(['registration_open','notifications_enabled']as $key){$v=request_string($_POST,$key);if(!in_array($v,['0','1'],true))throw new DomainException('Invalid setting.');$values[$key]=$v;}
    foreach(['session_timeout'=>[300,86400],'backup_retention_days'=>[1,3650]]as $key=>[$min,$max]){$v=filter_var($_POST[$key]??null,FILTER_VALIDATE_INT);if($v===false||$v<$min||$v>$max)throw new DomainException('Invalid '.$key);$values[$key]=(string)$v;}
    $term=positive_id($_POST['active_term_id']??null);if(!scalar('SELECT COUNT(*) FROM terms WHERE id=? AND is_active=1',[$term]))throw new DomainException('Choose an active term.');$values['active_term_id']=(string)$term;
    $gwaPolicy=positive_id($_POST['gwa_policy_id']??null);policy($gwaPolicy);$values['gwa_policy_id']=(string)$gwaPolicy;
    $schedule=request_string($_POST,'backup_schedule');if(!in_array($schedule,['manual','daily','weekly','monthly'],true))throw new DomainException('Invalid schedule.');$values['backup_schedule']=$schedule;
    if(($_FILES['logo']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$f=$_FILES['logo'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>1024*1024||!is_uploaded_file($f['tmp_name']))throw new DomainException('Choose a PNG or JPEG logo no larger than 1 MB.');$info=getimagesize($f['tmp_name']);if(!$info||!in_array($info['mime'],['image/png','image/jpeg'],true)||$info[0]>3000||$info[1]>3000)throw new DomainException('Choose a valid PNG or JPEG logo up to 3000 pixels.');$relative='uploads/logo-'.bin2hex(random_bytes(12)).($info['mime']==='image/png'?'.png':'.jpg');if(!move_uploaded_file($f['tmp_name'],dirname(__DIR__,2).'/'.$relative))throw new RuntimeException('Unable to save logo.');$values['logo_path']=$relative;}
    foreach($values as $key=>$value){$before=setting($key);query('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)',[$key,$value]);audit('settings_update','settings',null,'Updated '.$key,[$key=>$before],[$key=>$value]);}
},'settings.php');
page_start('System settings','Configuration changes are validated and recorded in the audit trail.');?><section class="panel"><form method="post" enctype="multipart/form-data" class="form-grid"><?php csrf_field();foreach(['school_name'=>'School name','campus'=>'Campus','report_header'=>'Report header']as $key=>$label)input_field($key,$label,setting($key));select_field('active_term_id','Active academic term',choices('terms','name','is_active=1'),setting('active_term_id'));select_field('gwa_policy_id','Dashboard / default report GWA interpretation',choices('grading_policies'),setting('gwa_policy_id','1'));select_field('registration_open','Allow account requests',[1=>'Yes',0=>'No'],setting('registration_open'));select_field('notifications_enabled','Stored notifications',[1=>'Enabled',0=>'Disabled'],setting('notifications_enabled'));input_field('session_timeout','Inactivity timeout (seconds)',setting('session_timeout'),'number',true,'min="300" max="86400"');input_field('backup_retention_days','Backup retention days',setting('backup_retention_days'),'number',true,'min="1" max="3650"');select_field('backup_schedule','CLI backup schedule',['manual'=>'Manual','daily'=>'Daily','weekly'=>'Weekly','monthly'=>'Monthly'],setting('backup_schedule'));input_field('logo','School logo (PNG/JPEG, max 1 MB)','','file',false,'accept="image/png,image/jpeg"');?><p class="wide text-secondary">Scheduling requires the documented cPanel cron command. Selecting a schedule alone does not install a server job. Configure immutable grading-policy versions in Academic setup.</p><button class="btn btn-primary">Save settings</button></form></section><?php page_end();
